#define rot(a)    mat2(cos(a+vec4(0,11,33,0)))        // rotation

void mainImage(out vec4 O, vec2 U)
{
    float t=9.; 

    vec3  R = iResolution, Y = vec3(0,1,0),
          D = normalize(vec3((U+U-R.xy)/R.y, -10.)),   // ray direction
          p = vec3(0,0,25), q,a,i,d,                   // marching point along ray 
          M = iMouse.z > 0. ? iMouse.xyz/R -.5: vec3(10,8,0)/1e2*cos(iTime+vec3(0,11,0))+vec3(0,.3,0); 

    for ( O=vec4(1); O.x > 0. && t > .005; O-=.01 ) {
        q = p,
        q.xz *= rot(-6.3*M.x),
        q.yz *= rot(.5-6.3*M.y),                      // rotations
        q.xy = abs(q.xy),
        t = max( min( abs(q.y-.1)-.05,                         // walls
                      max(q.y-.1 ,abs(q.z-1.02)-.015)),        // top
                 max( max(1. - length(q.xz),abs(q.z-.52)-.52) ,// carve main arc
                      q.x -3.*q.z*q.z -2.                      // carve terrain
               )     );
        if ( q.x > 1. ) q.x = mod(q.x,.5)-.25 , q.z-=.8,       // arcades
                        t = max(t,max(.22-length(q.xz),-max(q.z,abs(q.x)-.22))),
                        q.z+=.8;

        p += .5*t*D;                                  // step forward = dist to obj
    }
    O *= texture(iChannel0, 3.*(q.z>1.04 ? q.xy : q.y<.15 ? q.yz : q.zx)); // texturing
}
